import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"run","description":"","frontmatter":{},"headers":[],"relativePath":"cli/run.md","filePath":"cli/run.md","lastUpdated":1784743712000}'),r={name:"cli/run.md"};function s(n,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="run" tabindex="-1">run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;run&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Launch the interactive <strong>TUI (Terminal User Interface)</strong> API explorer. This is a full-screen application for searching, browsing, inspecting, and invoking API endpoints without leaving the terminal.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><ul><li>You want to explore your APIs interactively</li><li>You need to search for a specific endpoint across all specs</li><li>You want to browse the spec → collection → tag → endpoint hierarchy</li><li>You want to test an API call before configuring the MCP server</li></ul><h2 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Position</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>path</code></td><td>1</td><td>No</td><td>Workspace directory. If omitted, resolves via path resolution rules.</td></tr></tbody></table><h2 id="flags" tabindex="-1">Flags <a class="header-anchor" href="#flags" aria-label="Permalink to &quot;Flags&quot;">​</a></h2><p>None.</p><h2 id="modes" tabindex="-1">Modes <a class="header-anchor" href="#modes" aria-label="Permalink to &quot;Modes&quot;">​</a></h2><h3 id="search-mode" tabindex="-1">Search mode <a class="header-anchor" href="#search-mode" aria-label="Permalink to &quot;Search mode&quot;">​</a></h3><p>Full-text search across all endpoints in all specs. Supports filtering by HTTP method, tag, and path.</p><ul><li>Type a query to search endpoint names, paths, and descriptions</li><li>Filter results by method (GET, POST, PUT, DELETE, etc.)</li><li>View endpoint details with a single keystroke</li></ul><h3 id="browse-mode" tabindex="-1">Browse mode <a class="header-anchor" href="#browse-mode" aria-label="Permalink to &quot;Browse mode&quot;">​</a></h3><p>Tree navigation through the spec hierarchy:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spec → Collection → Tag → Endpoint</span></span></code></pre></div><ul><li>Navigate down the tree to find specific endpoints</li><li>View endpoint details (parameters, request body, responses)</li><li>Invoke the API directly from the TUI</li></ul><h2 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>Navigate up/down</td></tr><tr><td><code>Enter</code></td><td>Select or open</td></tr><tr><td><code>Esc</code></td><td>Go back</td></tr><tr><td><code>Tab</code></td><td>Switch between Search and Browse modes</td></tr><tr><td><code>/</code></td><td>Focus search input</td></tr><tr><td><code>q</code></td><td>Quit</td></tr></tbody></table><h2 id="post-command-verification" tabindex="-1">Post-command verification <a class="header-anchor" href="#post-command-verification" aria-label="Permalink to &quot;Post-command verification&quot;">​</a></h2><p>The TUI loads all specs from the workspace. If a spec fails to load, an error message is shown in the interface.</p><h2 id="nuances" tabindex="-1">Nuances <a class="header-anchor" href="#nuances" aria-label="Permalink to &quot;Nuances&quot;">​</a></h2><ul><li><strong>Auto-init:</strong> If no config file exists, <code>run</code> automatically runs the init wizard first.</li><li><strong>No flags:</strong> The <code>run</code> command has no flags — all configuration comes from the workspace.</li><li><strong>Terminal size:</strong> The TUI requires a terminal with at least 80×24 characters. It may not render correctly in very small terminals.</li><li><strong>Dependencies:</strong> The TUI uses Bubbletea. It works over SSH and in most terminal emulators.</li></ul>',25)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
